package main

import (
	"bytes"
	"fmt"
	"maps"
	"slices"

	"go.yaml.in/yaml/v3"
)

// header opens every generated file: the license line the license gate checks and the marker
// that tells readers and tools never to edit the file by hand (02 "Module register as the source").
const header = "# SPDX-License-Identifier: Apache-2.0\n" +
	"# Code generated by tools/archgen from architecture/modules.yaml. DO NOT EDIT.\n"

// generate renders the go-arch-lint configuration (format version 3) for the register.
//
// The output is byte-for-byte deterministic: modules keep the register order, platform packages and
// vendor groups are sorted by name (docs/DECISIONS.md M1-05/6), and the document is built as a
// yaml.Node tree, so no map iteration order reaches the file. The error is only an encoder failure.
func generate(r *register) ([]byte, error) {
	var buf bytes.Buffer
	buf.WriteString(header)
	enc := yaml.NewEncoder(&buf)
	enc.SetIndent(2)
	if err := enc.Encode(configNode(r)); err != nil {
		return nil, fmt.Errorf("encode config: %w", err)
	}
	if err := enc.Close(); err != nil {
		return nil, fmt.Errorf("encode config: %w", err)
	}
	return buf.Bytes(), nil
}

// Component names and paths that several rules share.
const (
	kernelCore  = "kernel-core"
	kernelPorts = "kernel-ports"
	internalDir = "internal/"
	boolTag     = "!!bool"

	componentWire        = "wire"
	componentCmd         = "cmd"
	componentAPI         = "api"
	componentTestSupport = "testsupport"
)

// The layer components of a module: <module>-domain, <module>-app and <module>-adapters.
func domainOf(m string) string   { return m + "-domain" }
func appOf(m string) string      { return m + "-app" }
func adaptersOf(m string) string { return m + "-adapters" }

func scalar(tag, value string) *yaml.Node {
	return &yaml.Node{Kind: yaml.ScalarNode, Tag: tag, Value: value}
}

func str(s string) *yaml.Node { return scalar("!!str", s) }

// flowList renders a list in flow style ([a, b]), which keeps component and rule lists on one
// line where they fit and makes diffs of the generated file easy to read.
func flowList(items []string) *yaml.Node {
	n := &yaml.Node{Kind: yaml.SequenceNode, Style: yaml.FlowStyle}
	for _, s := range items {
		n.Content = append(n.Content, str(s))
	}
	return n
}

func mapping() *yaml.Node { return &yaml.Node{Kind: yaml.MappingNode} }

func set(m *yaml.Node, key string, value *yaml.Node) {
	m.Content = append(m.Content, str(key), value)
}

// excludeTests keeps _test.go files out of the check: tests may import whatever they need
// (fakes, harnesses), and go-arch-lint would otherwise attribute those imports to the package.
const excludeTests = `^.*_test\.go$`

func configNode(r *register) *yaml.Node {
	root := mapping()
	set(root, "version", scalar("!!int", "3"))
	set(root, "workdir", str("."))

	// ignoreNotFoundComponents (docs/DECISIONS.md M1-05/3): go-arch-lint 1.19.0 fails for every "in"
	// pattern without a directory, and most layers of a module have no package yet. An unknown
	// component name and a package without component still fail.
	allow := mapping()
	set(allow, "depOnAnyVendor", scalar(boolTag, "false"))
	set(allow, "ignoreNotFoundComponents", scalar(boolTag, "true"))
	set(root, "allow", allow)

	set(root, "exclude", flowList(r.Exclude))
	files := flowList([]string{excludeTests})
	files.Content[0].Style = yaml.DoubleQuotedStyle
	set(root, "excludeFiles", files)
	set(root, "vendors", vendorsNode(r))
	set(root, "components", componentsNode(r))
	set(root, "commonComponents", flowList([]string{kernelCore}))
	set(root, "deps", depsNode(r))
	return root
}

func vendorsNode(r *register) *yaml.Node {
	n := mapping()
	for _, g := range slices.Sorted(maps.Keys(r.Vendors)) {
		entry := mapping()
		set(entry, "in", flowList(r.Vendors[g]))
		set(n, vendorName(g), entry)
	}
	return n
}

func vendorName(group string) string { return "v-" + group }

func vendorNames(groups []string) []string {
	names := make([]string, 0, len(groups))
	for _, g := range groups {
		names = append(names, vendorName(g))
	}
	return names
}

func platformNames(r *register) []string {
	return slices.Sorted(maps.Keys(r.Platform))
}

func platformComponent(p string) string { return "platform-" + p }

func platformComponents(r *register) []string {
	names := make([]string, 0, len(r.Platform))
	for _, p := range platformNames(r) {
		names = append(names, platformComponent(p))
	}
	return names
}

// moduleComponents returns the four components of a module: port, domain, app and adapters.
func moduleComponents(m string) []string {
	return []string{m, domainOf(m), appOf(m), adaptersOf(m)}
}

// component is one entry of the components section.
type component struct {
	name string
	in   []string
}

func prefixed(prefix string, names []string) []string {
	paths := make([]string, 0, len(names))
	for _, n := range names {
		paths = append(paths, prefix+n)
	}
	return paths
}

func tree(dir string) []string { return []string{dir, dir + "/**"} }

// migrationsComponent is the component of the package migrations (register section migrations).
const migrationsComponent = "migrations"

func components(r *register) []component {
	list := []component{
		{kernelCore, prefixed(internalDir+"kernel/", r.Kernel.Core)},
		{kernelPorts, prefixed(internalDir+"kernel/", r.Kernel.Ports)},
	}
	for _, p := range platformNames(r) {
		list = append(list, component{platformComponent(p), tree(internalDir + "platform/" + p)})
	}
	list = append(list, component{componentWire, tree(internalDir + componentWire)}, component{componentCmd, []string{"cmd/**"}})
	if r.API != nil {
		list = append(list, component{componentAPI, []string{"api/**"}})
	}
	if r.Migrations != nil {
		// Only the package itself: migrations-lint keeps the directory free of subdirectories.
		list = append(list, component{migrationsComponent, []string{"migrations"}})
	}
	for _, m := range r.moduleOrder {
		list = append(list,
			component{m, []string{internalDir + m}},
			component{domainOf(m), tree(internalDir + m + "/domain")},
			component{appOf(m), tree(internalDir + m + "/app")},
			component{adaptersOf(m), []string{internalDir + m + "/adapters/**"}},
		)
	}
	paths := make([]string, 0, len(r.TestSupport.Paths))
	for _, p := range r.TestSupport.Paths {
		paths = append(paths, p+"/**")
	}
	return append(list, component{componentTestSupport, paths})
}

func componentsNode(r *register) *yaml.Node {
	n := mapping()
	for _, c := range components(r) {
		entry := mapping()
		set(entry, "in", flowList(c.in))
		set(n, c.name, entry)
	}
	return n
}

// dep is one entry of the deps section. anything marks the testsupport rule, which allows every
// project package and every vendor library.
type dep struct {
	name        string
	mayDependOn []string
	canUse      []string
	anything    bool
}

// deps lists the rules. go-arch-lint lets a component import its own packages only if the
// component names itself in mayDependOn or is a common component, so every rule starts with its
// own component: a module has sub-packages in domain, app and adapters (sqlcgen, test helpers
// such as chattest), a platform package its test helper (pgtest), api/routes uses api/rest
// (docs/DECISIONS.md M1-05/14). kernel-core, the common component, would not need its rule and
// keeps it for the uniform rule (M1-05/28). kernel-ports has no rule: the kernel ports use no
// other port, only kernel-core (M1-05/15).
func deps(r *register) []dep {
	platforms := platformComponents(r)
	var api, migrations []string
	if r.API != nil {
		api = []string{componentAPI}
	}
	if r.Migrations != nil {
		migrations = []string{migrationsComponent}
	}
	list := []dep{{name: kernelCore, mayDependOn: []string{kernelCore}}}
	for _, p := range platformNames(r) {
		e := r.Platform[p]
		may := slices.Concat([]string{platformComponent(p), kernelPorts}, prefixed("platform-", e.DependsOn))
		if r.Migrations != nil && slices.Contains(r.Migrations.UsedBy, p) {
			may = append(may, migrationsComponent)
		}
		list = append(list, dep{name: platformComponent(p), mayDependOn: may, canUse: vendorNames(e.Vendors)})
	}

	var all []string
	for _, m := range r.moduleOrder {
		all = append(all, moduleComponents(m)...)
	}
	wire := slices.Concat([]string{componentWire}, all, platforms, []string{kernelPorts}, api, migrations)
	list = append(list,
		dep{name: componentWire, mayDependOn: wire, canUse: vendorNames(r.Wire.Vendors)},
		// cmd may use api: the tools of the binary (bothy import) call the server through the
		// generated client api/restclient (docs/DECISIONS.md D-M8-10-8).
		dep{name: componentCmd, mayDependOn: slices.Concat([]string{componentCmd, componentWire}, platforms, []string{kernelPorts}, api, migrations), canUse: vendorNames(r.Cmd.Vendors)},
	)
	if r.API != nil {
		list = append(list, dep{name: componentAPI, mayDependOn: api, canUse: vendorNames(r.API.Vendors)})
	}
	if r.Migrations != nil {
		list = append(list, dep{name: migrationsComponent, mayDependOn: migrations})
	}

	for _, m := range r.moduleOrder {
		e := r.Modules[m]
		list = append(list,
			dep{name: m, mayDependOn: []string{m, kernelPorts}},
			dep{name: domainOf(m), mayDependOn: []string{domainOf(m)}},
			dep{name: appOf(m), mayDependOn: slices.Concat([]string{appOf(m), m, domainOf(m), kernelPorts}, e.DependsOn)},
			dep{
				name:        adaptersOf(m),
				mayDependOn: slices.Concat([]string{adaptersOf(m), m, appOf(m), domainOf(m), kernelPorts}, platforms, api, e.DependsOn),
				canUse:      vendorNames(e.AdapterVendors),
			},
		)
	}
	return append(list, dep{name: componentTestSupport, anything: true})
}

// depsNode renders the deps section. An entry with neither components nor vendors is left out,
// because go-arch-lint rejects an empty mayDependOn; such a component may then use only the
// common component kernel-core, not even its own other packages.
func depsNode(r *register) *yaml.Node {
	n := mapping()
	for _, d := range deps(r) {
		entry := mapping()
		if d.anything {
			set(entry, "anyProjectDeps", scalar(boolTag, "true"))
			set(entry, "anyVendorDeps", scalar(boolTag, "true"))
		}
		if len(d.mayDependOn) > 0 {
			set(entry, "mayDependOn", flowList(d.mayDependOn))
		}
		if len(d.canUse) > 0 {
			set(entry, "canUse", flowList(d.canUse))
		}
		if len(entry.Content) > 0 {
			set(n, d.name, entry)
		}
	}
	return n
}
